"""Sorting helpers for lla listing records.

The reference's ordinary name sort compares names case-insensitively and
compares digit runs numerically.  This module accepts either dictionaries
(the JSON record shape) or objects exposing the same attributes.
"""
import re


def _get(item, key, default=None):
    return item.get(key, default) if isinstance(item, dict) else getattr(item, key, default)


def natural_key(value, case_sensitive=False):
    value = str(value)
    if not case_sensitive:
        value = value.casefold()
    return tuple((1, int(part)) if part.isdigit() else (0, part)
                 for part in re.split(r"(\d+)", value))


def sort_records(records, criterion="name", reverse=False, dirs_first=False,
                 case_sensitive=False, natural=True):
    """Return a sorted copy of records using name, size, or date ordering.

    `reverse` applies to the complete ordering, including the directory-first
    grouping, matching the CLI behavior.
    """
    key_name = lambda x: natural_key(_get(x, "name", ""), case_sensitive) if natural else (
        str(_get(x, "name", "")) if case_sensitive else str(_get(x, "name", "")).casefold())
    if criterion == "size":
        key = lambda x: (_get(x, "size_bytes", _get(x, "size", 0)) or 0, key_name(x))
    elif criterion == "date":
        key = lambda x: (_get(x, "modified", _get(x, "modified_time", 0)) or 0, key_name(x))
    else:
        key = key_name
    result = list(records)
    if dirs_first:
        result.sort(key=lambda x: (_get(x, "file_type", "") not in ("dir", "directory"), key(x)),
                    reverse=reverse)
    else:
        result.sort(key=key, reverse=reverse)
    return result
"""Permission strings used by lla's long listing formatter."""

import stat


def file_type(mode: int) -> str:
    if stat.S_ISDIR(mode):
        return "dir"
    if stat.S_ISLNK(mode):
        return "link"
    if stat.S_ISREG(mode):
        return "file"
    if stat.S_ISFIFO(mode):
        return "fifo"
    if stat.S_ISSOCK(mode):
        return "socket"
    if stat.S_ISCHR(mode):
        return "char"
    if stat.S_ISBLK(mode):
        return "block"
    return "other"


def type_char(mode: int) -> str:
    return {"dir": "d", "link": "l", "file": "-", "fifo": "p",
            "socket": "s", "char": "c", "block": "b"}.get(file_type(mode), "?")


def format_permissions(mode: int, fmt: str = "symbolic") -> str:
    """Format an st_mode value using the CLI's permission-format names."""
    kind = file_type(mode)
    bits = mode & 0o777
    octal = f"{bits:03o}"
    if fmt == "compact":
        return octal
    if fmt == "octal":
        return type_char(mode) + octal
    if fmt == "binary":
        return type_char(mode) + f"{bits:09b}"
    if fmt == "verbose":
        def triplet(value: int) -> str:
            return "".join(c if value & bit else "-" for c, bit in (("r", 4), ("w", 2), ("x", 1)))
        return f"type:{kind} owner:{triplet((bits >> 6) & 7)} group:{triplet((bits >> 3) & 7)} others:{triplet(bits & 7)}"
    chars = "".join(c if bits & bit else "-" for bit, c in (
        (0o400, "r"), (0o200, "w"), (0o100, "x"),
        (0o040, "r"), (0o020, "w"), (0o010, "x"),
        (0o004, "r"), (0o002, "w"), (0o001, "x")))
    # The reference long formatter repeats its symbolic permission segment three
    # times (including the file type marker).
    return (type_char(mode) + chars) * 3
"""Plugin related CLI commands for lla."""
import os
import sys
from pathlib import Path


LIST_HELP = """executable-list-plugins 
List all available plugins

USAGE:
    executable list-plugins

OPTIONS:
    -h, --help    Print help information
"""

PLUGIN_HELP = """executable-plugin 
Run a plugin action

USAGE:
    executable plugin [OPTIONS] [--] [ARGS]

ARGS:
    <plugin_name>       Name of the plugin
    <plugin_action>     Action to perform
    <plugin_args>...    Arguments for the plugin action

OPTIONS:
    -a, --action <action>    Action to perform (alternative to positional)
    -h, --help               Print help information
    -n, --name <name>        Name of the plugin (alternative to positional)
    -r, --args <args>...     Arguments for the plugin action (alternative to positional)
"""


def _plugin_dir():
    # Match the documented default; installed plugins are shared objects.
    cfg = Path.home() / ".config/lla/config.toml"
    try:
        import re
        txt = cfg.read_text()
        m = re.search(r'(?m)^plugins_dir\s*=\s*["\']([^"\']+)', txt)
        if m:
            return Path(os.path.expanduser(m.group(1)))
    except OSError:
        pass
    return Path.home() / ".config/lla/plugins"


def _libraries():
    """Return loadable ELF candidates and loader diagnostics."""
    found, warnings = [], []
    try:
        entries = _plugin_dir().iterdir()
    except OSError:
        return found, warnings
    for p in entries:
        if not p.is_file() or p.suffix.lower() not in (".so", ".dll", ".dylib"):
            continue
        try:
            magic = p.open("rb").read(4)
        except OSError:
            continue
        if magic == b"\x7fELF":
            found.append(p.stem)
        else:
            warnings.append(f'⚠️ Failed to load plugin library "{p}": {p}: file too short')
    return found, warnings


def run(args):
    """Dispatch plugin subcommands; return True if consumed."""
    if not args or args[0] not in ("plugin", "list-plugins"):
        return False
    cmd, rest = args[0], args[1:]
    if cmd == "list-plugins":
        if any(a in ("-h", "--help") for a in rest):
            print(LIST_HELP)
        else:
            found, warnings = _libraries()
            for warning in warnings:
                print(warning)
            if not found:
                print("╭─ Plugins ───────────────────────────────────╮")
                print("│   ℹ  No plugins installed.                  │")
                print("│                                             │")
                print("│      Run lla install --help to get started. │")
                print("╰─────────────────────────────────────────────╯")
            else:
                print("╭─ Plugins ───────────────────────────────────╮")
                for name in sorted(found):
                    print(f"│   {name}")
                print("╰─────────────────────────────────────────────╯")
        return True

    if any(a in ("-h", "--help") for a in rest):
        print(PLUGIN_HELP)
        return True
    name = None
    positional = []
    i = 0
    while i < len(rest):
        if rest[i] in ("-n", "--name") and i + 1 < len(rest):
            name = rest[i + 1]; i += 2
        elif rest[i] in ("-a", "--action") and i + 1 < len(rest):
            positional.extend((name or "", rest[i + 1])); i += 2
        elif rest[i] in ("-r", "--args"):
            positional.extend(rest[i+1:]); break
        elif rest[i] == "--":
            positional.extend(rest[i+1:]); break
        elif not rest[i].startswith("-"):
            positional.append(rest[i]); i += 1
        else:
            i += 1
    if name:
        positional.insert(0, name)
    plugin = positional[0] if positional else ""
    if not plugin:
        print("""\n✗ Plugin Error

  Plugin name is required.

  Usage:
    lla plugin <name> <action> [args...]
    lla plugin --name <name> --action <action> [--args ...]

  Examples:
    lla plugin git_status help
    lla plugin file_tagger add-tag README.md important

  Run 'lla list-plugins' to see available plugins.
""")
    else:
        _, warnings = _libraries()
        for warning in warnings:
            print(warning)
        print("\n✗ Plugin Error\n\n  Plugin '%s' not found.\n  \n  No plugins are currently installed. Run 'lla install' to install plugins.\n" % plugin)
    return True
"""Small implementation of lla's non-interactive theme install command."""
import os
import shutil
import sys
import re
from pathlib import Path


def install(path: str) -> int:
    source = Path(path).expanduser()
    if not source.exists():
        print(f"\n✗ Error\n\n  Path does not exist: {path}\n")
        return 1
    if source.is_file():
        if source.suffix != ".toml":
            print("\n✗ Error\n\n  Theme file must have .toml extension\n")
            return 1
        files = [source]
    elif source.is_dir():
        files = sorted(source.glob("*.toml"), key=lambda p: p.name)
    else:
        files = []
    if not files:
        print("No themes were installed")
        return 0
    dest = Path.home() / ".config" / "lla" / "themes"
    dest.mkdir(parents=True, exist_ok=True)
    for file in files:
        shutil.copy2(file, dest / file.name)
        print(f"✓ Installed theme: {file.name}")
    print(f"\n{len(files)} theme(s) installed successfully!\nUse lla theme to select a theme")
    return 0


def preview(name: str) -> int:
    roots = [Path.home() / ".config" / "lla" / "themes"]
    candidates = []
    for root in roots:
        candidates.extend([root / (name + ".toml"), root / name])
    theme_path = next((p for p in candidates if p.is_file()), None)
    data = {}
    if theme_path:
        try:
            raw = theme_path.read_text(encoding="utf-8")
            for key in ("name", "author", "description"):
                match = re.search(r"(?m)^\s*" + key + r"\s*=\s*\"((?:[^\"\\]|\\.)*)\"", raw)
                if match:
                    data[key] = bytes(match.group(1), "utf-8").decode("unicode_escape")
        except Exception:
            data = {}
    if not theme_path:
        print(f"\n✗ Error\n\n  Theme '{name}' not found. Install it with `lla theme pull` or place it in ~/.config/lla/themes\n")
        return 1
    title = data.get("name") or name
    author = data.get("author") or "Unknown"
    notes = data.get("description") or "No description"
    print(f"\nTheme preview: {title}\nAuthor : {author}\nNotes  : {notes}\n\nCore palette\n Files       Dirs        Symlinks    Exec        Size        Date       \n\nSample directory listing\nDefault view (lla)\n   src/\n   Cargo.toml\n   scripts/build.sh\n   current -> releases/2025\n   .env\n\nLong view (lla -l)\nPermissions  Size Modified     User Group Name\ndrwxr-xr-x   4.0K Nov 15 10:22 mona staff  src/\n-rw-r--r--   2.4K Nov 14 18:02 mona staff  Cargo.toml\n-rwxr-xr-x   8.8K Nov 13 09:10 mona staff  scripts/build.sh\nlrwxrwxrwx     9B Nov 12 08:01 mona staff  current -> releases/2025\n-rw-r--r--   640B Nov 11 21:58 mona staff  .env\n\nSample search output\nrg --search \"theme\"\nsrc/main.rs:42     let theme = load_theme(name)?;\n         ^^^^\n1 match across 1 file\n")
    return 0


def run(args):
    if len(args) >= 2 and args[0] == "theme" and args[1] == "install":
        if len(args) < 3:
            print("error: The following required arguments were not provided:\n    <path>")
            return 2
        return install(args[2])
    if len(args) >= 3 and args[0] == "theme" and args[1] == "preview":
        return preview(args[2])
    return None


if __name__ == "__main__":
    sys.exit(install(sys.argv[1]))
